if(string.IsNullOrEmpty(SessionState.GetString("Bulldozer.Mining.TestSavePath",""))||string.IsNullOrEmpty(SessionState.GetString("Quarry.UI.TestPrefs","")))throw new System.Exception("Isolated tests required");
var ui=Bulldozer.UI.QuarryGameUI.Instance;var e=ui.equipment;var p=ui.player;var loading=Bulldozer.UI.CommonUI.Instance.GetComponentInChildren<Bulldozer.UI.LoadingPanel>(true);p.autoMine=false;p.CancelMining();var report=new System.Collections.Generic.List<string>();System.Action<bool,string> check=(ok,msg)=>report.Add((ok?"PASS ":"FAIL ")+msg);int stage=0,start=Time.frameCount;float began=Time.realtimeSinceStartup,tipAt=0;string oldTip="";
EditorApplication.isPaused=true;Time.captureDeltaTime=1f/30;ui.Open("settings");EditorApplication.CallbackFunction tick=null;System.Action done=()=>{System.IO.File.WriteAllLines("Maintenance/UI/interaction-verification.txt",report.Distinct());EditorApplication.update-=tick;Time.captureDeltaTime=0;};
tick=()=>{if(!EditorApplication.isPlaying){EditorApplication.update-=tick;return;}try{int f=Time.frameCount-start;if(stage==0&&f>=24){check(Time.timeScale==0&&p.InputBlocked,"Modal pauses game and blocks movement");check(ui.modal.panelGroup.alpha>.99f&&Mathf.Abs(ui.modal.dim.color.a-.55f)<.01f,"Unscaled opening reaches full panel and 55% dim");check(Vector3.Distance(ui.modal.panel.localScale,Vector3.one)<.001f,"Panel ends at exact original scale");ui.soundToggle.toggle.isOn=false;check(!Bulldozer.UI.QuarryUIFeedback.Sound&&AudioListener.volume==0,"Sound OFF mutes audio and saves preference");ui.soundToggle.toggle.isOn=true;ui.volume.value=.4f;check(Mathf.Abs(AudioListener.volume-.4f)<.001f,"Sound slider applies saved volume");ui.vibrationToggle.toggle.isOn=true;check(Bulldozer.UI.QuarryUIFeedback.Vibration,"Vibration setting saves");ui.TogglePerformance();check(ui.performanceOptions.activeSelf,"Performance dropdown opens");ui.SetPerformance(1);check(!ui.performanceOptions.activeSelf&&Application.targetFrameRate==60,"Performance choice applies and closes dropdown");for(int i=0;i<8;i++){ui.Close();ui.Open(i%2==0?"settings":"inventory");}stage=1;start=Time.frameCount;}
else if(stage==1&&f>=24){check(ui.modal.IsOpen&&ui.inventoryPage.activeSelf&&ui.modal.panelGroup.alpha>.99f&&Time.timeScale==0,"Rapid close/reopen leaves one interactive modal without scale drift");var s=e.Snapshot;s.items=new[]{0,0,6};s.coins=100;s.refineryInput=new[]{1};s.refineryOutput=new[]{8};s.loadingQueue=new[]{9};e.Commit(s);ui.SelectStorage(0);check(ui.inventoryCounts[0].text=="2 RAW   /   1 REFINED","Inventory displays actual raw/refined counts");ui.SelectStorage(2);check(ui.inventoryCounts[1].text.StartsWith("1 RAW")&&ui.inventoryCounts[2].text.EndsWith("1 REFINED"),"Refinery inventory tab reads both queues");ui.Open("upgrades");int cash=e.Cash;check(!ui.Purchase(0)&&e.Cash==cash,"Remote upgrade preview cannot bypass workbench");var cc=p.GetComponent<CharacterController>();cc.enabled=false;p.transform.position=new Vector3(ui.workbench.zone.bounds.center.x,.03f,ui.workbench.zone.bounds.center.z);cc.enabled=true;Physics.SyncTransforms();stage=2;start=Time.frameCount;}
else if(stage==2&&f>=24){check(ui.Purchase(0)&&ui.Purchase(1)&&ui.Purchase(2),"All three workbench upgrades purchase through new UI");check(e.DamageLevel==1&&e.CapacityLevel==1&&e.SpeedLevel==1&&e.Cash==55,"Upgrade amounts and cash debit match existing rules");stage=3;start=Time.frameCount;}
else if(stage==3&&f>=24){check(ui.upgradeIcons.All(r=>Vector3.Distance(r.localScale,Vector3.one)<.001f),"Upgrade icons return to unit scale");check(!ui.Purchase(0)&&e.Cash==55&&e.DamageLevel==1,"Insufficient funds preserves cash and level");var disk=new Bulldozer.Player.Persistence.MiningProgressStore(e.SavePath).Current;check(disk.coins==55&&disk.damageLevel==1&&disk.capacityLevel==1&&disk.speedLevel==1,"UI purchases persist to disk");ui.Open("confirmation");ui.ResetSettings();check(Bulldozer.UI.QuarryUIFeedback.Sound&&!Bulldozer.UI.QuarryUIFeedback.Vibration&&e.Cash==55,"Settings reset leaves game progression unchanged");ui.Close();check(ui.modal.gameObject.activeSelf&&p.InputBlocked,"Closing modal blocks input until animation ends");stage=4;start=Time.frameCount;}
else if(stage==4&&f>=24){check(!ui.modal.gameObject.activeSelf&&Time.timeScale==1&&!p.InputBlocked,"Close disables modal and restores play");loading.Show();loading.Report(1,"Loading test");tipAt=Time.unscaledTime;oldTip=loading.tip.text;stage=5;start=Time.frameCount;}
else if(stage==5&&f>=24){check(loading.BlocksInput&&loading.DisplayedProgress<1&&loading.percentage.text!="100%","Loading never displays 100% before ready");check(loading.artTransform.localScale.x>=1&&loading.artTransform.localScale.x<=1.0251f,"Artwork push-in stays restrained and uniform");if(Time.unscaledTime-tipAt>=5.5f){check(loading.tip.text!=oldTip,"Tips crossfade after five seconds while loading continues");Bulldozer.UI.CommonUI.Instance.StartCoroutine(loading.Reveal());stage=6;start=Time.frameCount;}}
else if(stage==6&&f>=30){check(!loading.IsVisible&&!loading.BlocksInput,"Ready bar completes and loading cover releases input");check(UnityEngine.Object.FindObjectsByType<UnityEngine.EventSystems.EventSystem>(FindObjectsSortMode.None).Count(x=>x.isActiveAndEnabled)==1,"Exactly one active EventSystem");check(ui.notification.gameObject.activeSelf||!ui.notification.blocksRaycasts,"Queued rewards never block controls");done();return;}
if(Time.realtimeSinceStartup-began>120){report.Add("FAIL timeout at stage "+stage);done();return;}EditorApplication.Step();}catch(System.Exception ex){report.Add("FAIL "+ex);done();}};EditorApplication.update+=tick;return "Testing modals, settings, inventory, purchases, error feedback, loading and queued notifications";

